style.css:
@-moz-document domain("roblox.com") {
@keyframes rainbow {
    0% {background-color: #FFC7D1;border-color: #FFC0CB;}
    14% {background-color: #FFABBA;border-color: #FFC0CB;}
    28% {background-color: #FF8FA3;border-color: #FFC0CB;}
    42% {background-color: #FF748C;border-color: #FFC0CB;}
    56% {background-color: #FF748C;border-color: #FFC0CB;}
    80% {background-color: #FF8FA3;border-color: #FFC0CB;}
    94% {background-color: #FFABBA;border-color: #FFC0CB;}
    100% {background-color: #FFC7D1;border-color: #FFC0CB;}
}

  
.btn-common-play-game-lg {
    animation: rainbow 10s infinite;
}

.friend-carousel-container {
	border: 2px solid pink !important;
  border-radius: 15px !important;
  background-color: rgba(255, 192, 203, 0.8) !important;
}

.container-fluid{
	border: 2px solid #f4bded;
  padding: 0px;
  border-bottom-left-radius: 50px 20px;
  border-bottom-right-radius: 50px 20px;
  background-color: rgba(255, 192, 203, 0.5) !important;
}

.width-\[288px\] {
	border: 2px solid pink !important;
  border-top-right-radius: 50px 20px;
  border-bottom-right-radius: 50px 20px;
  background-color: rgba(255, 192, 203, 0.5) !important;
}

body, .content
   {
     background:transparent!important;
   }

.dark-theme, .light-theme, .nav-content
  {
    width: 100% !important;
    height: 100% !important;
    background-size: cover !important;
    background-attachment: fixed !important;
    background-position: center !important;
    background-image: url("data:image/jpeg;base64,")!important;
}

#game-detail-page {
border: 2px solid pink !important;
  border-top-right-radius: 100px 50px;
  border-bottom-left-radius: 100px 50px;
  background-color: rgba(255, 192, 203, 0.5) !important;
}

#chat-main,.dialog-main {
  border: 2px solid pink !important;
  border-top-right-radius: 50px 20px;
  border-top-left-radius: 50px 20px;
  background-color: rgba(255, 192, 203, 0.8) !important;
}

.border-top{
  border: 2px solid pink !important;
  border-top-right-radius: 50px 20px;
  border-top-left-radius: 50px 20px;
  background-color: rgba(255, 157, 174, 0.8) !important;
}

body, p, span, a, h1, h2, h3, h4, h5, h6, label {
    color: #FF3292 !important;
}

  .load-more-button  {
    background: transparent!important;
  }

  [role="alert"],.content-region,.yt-uix-checkbox-on-off .checked:before  {
    display: none!important;
  }

  :not(#​) :link  {
    color: #ff0077!important;
  }

  :not(#​) :visited  {
    color: #ff3dbb!important;
  }

 .absolute {
	border: 2px solid pink !important;
  border-radius: 15px !important;
  background-color: rgba(255, 192, 203, 0.5) !important;
}

.gap-y-medium {
	border: 2px solid pink !important;
  border-radius: 15px !important;
  background-color: rgba(255, 192, 203, 0.5) !important;
}
#nav-charts-md-link,#nav-marketplace-md-link,#header-develop-md-link,#navigation-robux-container {
  height : 30px;
	border: 2px solid pink !important;
  border-radius: 15px !important;
  background-color: rgba(255, 192, 203, 0.5) !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
}

#header {
	border: 0px solid pink !important;
}

.game-card-link,#collection-carousel-item,.friends-carousel-tile,.list-item,.container-list,.message-banner {
  border: 2px solid pink !important;
  border-radius: 15px !important;
  background-color: rgba(255, 192, 203, 0.5) !important;
}

.dropdown-menu,.search-landing-container,#navbar-search-input,.btn-growth-xs,.filters-modal-container,.filter-select,.topic,.catalog-item-container,.foundation-web-list,.private-message-row {
  border: 2px solid pink !important;
  border-radius: 15px !important;
  background-color: rgba(255, 192, 203, 0.9) !important;
}

.catalog-header {
  border: 2px solid pink !important;
  border-radius: 15px !important;
  background-color: rgba(255, 133, 154, 0.9) !important;
}

.left-nav,.navbar-fixed-top,.alert,.content-emphasis,.container-footer,.chat-windows-header,.dialog-container,.rbx-scrollbar,.min-width-0,.info-container,.rbx-tab-heading,.avatar-card-container,.search-bars,.topic-container {
    background-color: transparent!important;
}

#footer-container {
    border: 2px solid pink !important;
  border-top-right-radius: 50px 20px;
  border-top-left-radius: 50px 20px;
  background-color: rgba(255, 157, 174, 0.5) !important;
}

.profile-platform-container,.messages-container,.card-item,.group-details-container-desktop-and-tablet,.group-section-content{
  border: 2px solid #f4bded;
  padding: 0px;
  border-bottom-left-radius: 50px 20px;
  border-bottom-right-radius: 50px 20px;
  border-top-left-radius: 50px 20px;
  border-top-right-radius: 50px 20px;
  background-color: rgba(255, 192, 203, 0.5) !important;
}

.justify-center,.rbx-tab,.avatar-card-btns,.section-content-off,.menu-option,.menu-secondary-option,.groups-list-sidebar{
  border: 2px solid #f4bded;
  background-color: rgba(255, 192, 203, 0.9) !important;
}

.tab-horizontal-submenu,.container-empty{
  border: 2px solid pink !important;
  border-radius: 15px !important;
  background-color: rgba(255, 50, 146, 0.9) !important;
}
}
